
.char-status {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.char-name {
  font-size: 1rem;
  font-weight: bold;
  color: var(--c-accent);
  border-bottom: 2px solid var(--c-primary);
  padding-bottom: 4px;
  margin-bottom: 2px;
}

.field {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  border-bottom: 1px dashed var(--c-border);
  padding-bottom: 6px;
}

.label {
  flex: 0 0 64px;
  color: var(--c-text-muted);
  font-size: 0.8rem;
  font-weight: bold;
}

.value {
  flex: 1;
  color: var(--c-text);
  white-space: pre-wrap;
}
